<template>
	<div class="flex flex-col h-full w-full" v-if="isFormReady">
		<div class="w-full h-full bg-white sm:w-96 flex flex-col">
			<header
				class="flex flex-row bg-white shadow-sm py-4 px-3 items-center sticky top-0 z-[1000]"
			>
				<Button
					variant="ghost"
					class="!pl-0 hover:bg-white"
					@click="router.back()"
				>
					<FeatherIcon name="chevron-left" class="h-5 w-5" />
				</Button>
				<div
					v-if="id"
					class="flex flex-row items-center gap-2 overflow-hidden grow"
				>
					<h2
						class="text-xl font-semibold text-gray-900 whitespace-nowrap overflow-hidden text-ellipsis"
					>
						{{ __(props.doctype) }}
					</h2>
					<Badge
						:label="id"
						class="whitespace-nowrap text-[8px] overflow-hidden"
						variant="outline"
					/>
					<Badge
						v-if="status"
						:label="__(displayStatus, null, doctype)"
						:theme="statusColor"
						class="whitespace-nowrap text-[8px] overflow-hidden"
					/>

					<!--
						The header clips its overflow, so the actions are grouped and
						pinned shrink-0: on a narrow phone the title and badges give up
						width instead of pushing these off the edge.
						Share actions appear only once saved -- there is no link to an
						unnamed document.
					-->
					<div class="ml-auto flex items-center shrink-0">
						<CopyLinkButton
							v-if="canShare"
							:doctype="props.doctype"
							:name="id"
						/>
						<NotifyApproverButton
							v-if="canShare"
							:doctype="props.doctype"
							:name="id"
						/>

						<Dropdown
							:options="[
								{
									label: __('Delete'),
									condition: showDeleteButton,
									onClick: () => (showDeleteDialog = true),
								},
								{
									label: __('Cancel Application'),
									condition: () => canCancelOwnLeave.value,
									onClick: () => (showCancelOwnLeaveDialog = true),
								},
								{ label: __('Reload'), onClick: () => reloadDoc() },
							]"
							:button="{
								label: __('Menu'),
								icon: 'more-horizontal',
								variant: 'ghost',
							}"
						/>
					</div>
				</div>
				<h2 v-else class="text-2xl font-semibold text-gray-900">
					{{ __('New {0}', [__(doctype)], props.doctype) }}
				</h2>
			</header>

			<!-- Form -->
			<div class="bg-white grow overflow-y-auto">
				<!-- Tabs -->
				<template v-if="tabbedView">
					<div
						class="px-4 sticky top-0 z-[100] bg-white text-sm font-medium text-center text-gray-500 border-b border-gray-200 dark:text-gray-400 dark:border-gray-700"
					>
						<ul class="flex -mb-px overflow-auto hide-scrollbar">
							<li class="mr-2 whitespace-nowrap" v-for="tab in tabs">
								<button
									@click="activeTab = tab.name"
									class="inline-block py-4 px-2 border-b-2 border-transparent rounded-t-lg"
									:class="[
										activeTab === tab.name
											? '!text-gray-800 !border-gray-800'
											: 'hover:text-gray-600 hover:border-gray-300',
									]"
								>
									{{ __(tab.name, null, props.doctype) }}
								</button>
							</li>
						</ul>
					</div>

					<template v-for="tab in slotTabs" :key="tab.name">
						<div v-show="tab.name === activeTab" class="h-full">
							<slot :name="tab.slot" :isFormReadOnly="isFormReadOnly"></slot>
						</div>
					</template>

					<template v-for="(fieldList, tabName, index) in tabFields">
						<div
							v-show="tabName === activeTab"
							class="flex flex-col space-y-4 p-4"
						>
							<template v-for="field in fieldList" :key="field.fieldname">
								<slot
									v-if="field.fieldtype == 'Table'"
									:name="field.fieldname"
									:isFormReadOnly="isFormReadOnly"
								></slot>

								<FormField
									v-else
									:fieldtype="field.fieldtype"
									:fieldname="field.fieldname"
									v-model="formModel[field.fieldname]"
									:default="field.default"
									:label="__(field.label, null, props.doctype)"
									:options="field.options"
									:linkFilters="field.linkFilters"
									:documentList="field.documentList"
									:readOnly="isFieldReadOnly(field)"
									:reqd="Boolean(field.reqd)"
									:hidden="isFieldHidden(field)"
									:errorMessage="field.error_message"
									:minDate="field.minDate"
									:maxDate="field.maxDate"
									:addSectionPadding="fieldList[0].name !== field.name"
									:doctype="props.doctype"
									:quickOptions="field.quickOptions"
									:segmentOptions="field.segmentOptions"
									:placeholder="field.placeholder"
									:highlight="Boolean(field.highlight)"
									:hint="field.hint"
									:timeWindow="field.timeWindow"
									:noSeconds="Boolean(field.noSeconds)"
								/>
							</template>

							<!-- Attachment upload -->
							<div
								class="flex flex-row gap-2 items-center justify-center p-5"
								v-if="isFileUploading"
							>
								<LoadingIndicator class="w-3 h-3 text-gray-800" />
								<span class="text-gray-900 text-sm">{{ __("Uploading...") }} </span>
							</div>

							<FileUploaderView
								v-else-if="showAttachmentView && index === 0"
								v-model="fileAttachments"
								@handleFileSelect="handleFileSelect"
								@handleFileDelete="handleFileDelete"
							/>
						</div>
					</template>
				</template>

				<div class="flex flex-col space-y-4 p-4" v-else>
					<slot name="formHeader"></slot>
					<FormField
						v-for="field in displayFields"
						:key="field.name"
						:fieldtype="field.fieldtype"
						:fieldname="field.fieldname"
						v-model="formModel[field.fieldname]"
						:default="field.default"
						:label="__(field.label, null, props.doctype)"
						:options="field.options"
						:linkFilters="field.linkFilters"
						:documentList="field.documentList"
						:readOnly="isFieldReadOnly(field)"
						:reqd="Boolean(field.reqd)"
						:hidden="isFieldHidden(field)"
						:errorMessage="field.error_message"
						:minDate="field.minDate"
						:maxDate="field.maxDate"
						:doctype="props.doctype"
						:quickOptions="field.quickOptions"
						:segmentOptions="field.segmentOptions"
						:placeholder="field.placeholder"
						:highlight="Boolean(field.highlight)"
						:hint="field.hint"
						:timeWindow="field.timeWindow"
						:noSeconds="Boolean(field.noSeconds)"
					/>

					<!-- Attachment upload -->
					<div
						class="flex flex-row gap-2 items-center justify-center p-5"
						v-if="isFileUploading"
					>
						<LoadingIndicator class="w-3 h-3 text-gray-800" />
						<span class="text-gray-900 text-sm">{{ __("Uploading...") }} </span>
					</div>

					<FileUploaderView
						v-else-if="showAttachmentView"
						v-model="fileAttachments"
						@handleFileSelect="handleFileSelect"
						@handleFileDelete="handleFileDelete"
					/>
				</div>
			</div>

			<!-- Form Primary/Secondary Button -->
			<!-- custom form button eg: Download button in salary slips -->
			<div
				v-if="!showFormButton"
				class="px-4 pt-4 pb-4 standalone:pb-safe-bottom sm:w-96 bg-white sticky bottom-[var(--ion-tab-bar-height,3.5rem)] w-full drop-shadow-xl z-50 border-t rounded-t-lg"
			>
				<slot name="formButton"></slot>
			</div>

			<!-- workflow actions -->
			<WorkflowActionSheet
				v-else-if="!isFormDirty && workflow?.hasWorkflow"
				:doc="documentResource.doc"
				:workflow="workflow"
				@workflowApplied="reloadDoc()"
			/>

			<!-- save/submit/cancel -->
			<div
				v-else-if="isFormDirty || (!workflow?.hasWorkflow && formButton)"
				class="px-4 pt-4 pb-4 standalone:pb-safe-bottom sm:w-96 bg-white sticky bottom-[var(--ion-tab-bar-height,3.5rem)] w-full drop-shadow-xl z-50 border-t rounded-t-lg"
			>
				<ErrorMessage
					class="mb-2"
					:message="
						formErrorMessage ||
						docList?.insert?.error ||
						documentResource?.setValue?.error
					"
				/>

				<Button
					class="w-full rounded py-5 text-base disabled:bg-gray-700 disabled:text-white"
					:class="formButton === 'Cancel' ? 'shadow' : ''"
					@click="isSaveAction ? saveForm() : submitOrCancelForm()"
					:variant="formButton === 'Cancel' ? 'subtle' : 'solid'"
					:loading="
						docList.insert.loading ||
						documentResource?.setValue?.loading ||
						props.submitLoading
					"
				>
					{{ __(formButton) }}
				</Button>
			</div>

			<div
				v-if="canCancelOwnLeave"
				class="px-4 pb-4 standalone:pb-safe-bottom sm:w-96 bg-white w-full"
				:class="isFormDirty || (!workflow?.hasWorkflow && formButton) ? '' : 'pt-4 border-t drop-shadow-xl z-50 sticky bottom-[var(--ion-tab-bar-height,3.5rem)]'"
			>
				<Button
					class="w-full rounded py-5 text-base"
					variant="subtle"
					theme="red"
					@click="showCancelOwnLeaveDialog = true"
				>
					{{ __("Cancel Application") }}
				</Button>
			</div>
		</div>
	</div>

	<!-- Confirmation Dialogs -->
	<Dialog v-model="showDeleteDialog">
		<template #body-title>
			<h2 class="text-xl font-bold">{{ __("Delete {0}", [__(props.doctype)]) }}</h2>
		</template>
		<template #body-content>
			<p>
				{{ __("Are you sure you want to delete the {0}", [__(props.doctype)])  }}
				<span class="font-bold">{{ formModel.name }}</span>
				?
			</p>
		</template>
		<template #actions>
			<div class="flex flex-row gap-4">
				<Button
					variant="outline"
					class="py-5 w-full"
					@click="showDeleteDialog = false"
				>
					{{ __("Cancel") }}
				</Button>
				<Button
					variant="solid"
					theme="red"
					@click="handleDocDelete"
					class="py-5 w-full"
				>
					{{__("Delete") }}
				</Button>
			</div>
		</template>
	</Dialog>

	<Dialog v-model="showSubmitDialog">
		<template #body-title>
			<h2 class="text-xl font-bold">{{ __("Confirm") }} </h2>
		</template>
		<template #body-content>
			<p>
				{{ __("Permanently submit {0}", [__(props.doctype)]) }}
				<span class="font-bold">{{ formModel.name }}</span>
				?
			</p>
		</template>
		<template #actions>
			<div class="flex flex-row gap-4">
				<Button
					variant="outline"
					class="py-5 w-full"
					@click="showSubmitDialog = false"
				>
					{{ __("No") }}
				</Button>
				<Button
					variant="solid"
					@click="handleDocUpdate('submit')"
					class="py-5 w-full"
				>
					{{ __("Yes") }}
				</Button>
			</div>
		</template>
	</Dialog>

	<Dialog v-model="showCancelDialog">
		<template #body-title>
			<h2 class="text-xl font-bold">{{ __("Confirm") }} </h2>
		</template>
		<template #body-content>
			<p>
				{{ __("Permanently cancel {0}", [__(props.doctype)]) }}
				<span class="font-bold">{{ formModel.name }}</span
				>?
			</p>
		</template>
		<template #actions>
			<div class="flex flex-row gap-4">
				<Button
					variant="outline"
					class="py-5 w-full"
					@click="showCancelDialog = false"
				>
					{{ __("No") }}
				</Button>
				<Button
					variant="solid"
					@click="handleDocUpdate('cancel')"
					class="py-5 w-full"
				>
					{{ __("Yes") }}
				</Button>
			</div>
		</template>
	</Dialog>

	<Dialog v-model="showCancelOwnLeaveDialog">
		<template #body-title>
			<h2 class="text-xl font-bold">{{ __("Cancel Leave Application") }}</h2>
		</template>
		<template #body-content>
			<p>
				{{
					__(
						"This will withdraw the application so you can submit a corrected one. This cannot be undone."
					)
				}}
			</p>
		</template>
		<template #actions>
			<div class="flex flex-row gap-4">
				<Button
					variant="outline"
					class="py-5 w-full"
					@click="showCancelOwnLeaveDialog = false"
				>
					{{ __("Keep") }}
				</Button>
				<Button
					variant="solid"
					theme="red"
					class="py-5 w-full"
					:loading="cancellingOwnLeave"
					@click="cancelOwnLeaveApplication"
				>
					{{ __("Cancel Application") }}
				</Button>
			</div>
		</template>
	</Dialog>

	<Dialog v-model="showCnrDraftDialog">
		<template #body-title>
			<h2 class="text-xl font-bold">{{ __("Application Submitted") }}</h2>
		</template>
		<template #body-content>
			<p>
				{{
					__(
						"You have submitted this {0}. It is now waiting for your Leave Approver to approve it.",
						[__(props.doctype)]
					)
				}}
			</p>
		</template>
		<template #actions>
			<Button
				variant="solid"
				class="py-5 w-full"
				@click="confirmCnrDraftDialog"
			>
				{{ __("OK") }}
			</Button>
		</template>
	</Dialog>
</template>

<script setup>
import { computed, inject, nextTick, onMounted, ref, watch } from "vue"
import { useRouter } from "vue-router"
import {
	ErrorMessage,
	Badge,
	FeatherIcon,
	createListResource,
	createDocumentResource,
	toast,
	createResource,
	Dropdown,
	Dialog,
	LoadingIndicator,
	call,
} from "frappe-ui"
import FormField from "@/components/FormField.vue"
import FileUploaderView from "@/components/FileUploaderView.vue"
import WorkflowActionSheet from "@/components/WorkflowActionSheet.vue"

import { FileAttachment, guessStatusColor } from "@/composables"
import useWorkflow from "@/composables/workflow"
import { getCompanyCurrency } from "@/data/currencies"
import { myLeaves, leaveBalance } from "@/data/leaves"
import { formatCurrency } from "@/utils/formatters"
import { markAttendanceRefresh } from "@/utils/attendance_refresh"
import CopyLinkButton from "@/components/CopyLinkButton.vue"
import NotifyApproverButton from "@/components/NotifyApproverButton.vue"
import { isShareable } from "@/utils/application_share"

const props = defineProps({
	doctype: {
		type: String,
		required: true,
	},
	modelValue: {
		type: Object,
		required: true,
	},
	isSubmittable: {
		type: Boolean,
		required: false,
		default: false,
	},
	fields: {
		type: Array,
		required: true,
	},
	id: {
		type: String,
		required: false,
	},
	tabbedView: {
		type: Boolean,
		required: false,
		default: false,
	},
	tabs: {
		type: Array,
		required: false,
	},
	showAttachmentView: {
		type: Boolean,
		required: false,
		default: false,
	},
	showFormButton: {
		type: Boolean,
		required: false,
		default: true,
	},
	customSubmit: {
		type: Boolean,
		required: false,
		default: false,
	},
	submitLoading: {
		type: Boolean,
		required: false,
		default: false,
	},
})
const emit = defineEmits(["validateForm", "update:modelValue", "submitDocument"])
const router = useRouter()

const CNR_DOCTYPES = [
	"Late Entry Application",
	"Early Exit Application",
	"Out of Office Application",
]

const __ = inject("$translate")
const employee = inject("$employee")

// Share actions need a saved document to point at, and only make sense on the
// application types someone else has to approve.
const canShare = computed(() => Boolean(props.id && isShareable(props.doctype)))

let activeTab = ref(props.tabs?.[0].name)
let fileAttachments = ref([])
let statusColor = ref("")
let formErrorMessage = ref("")
let isFormDirty = ref(false)
let isFormUpdated = ref(false)
let showDeleteDialog = ref(false)
let showSubmitDialog = ref(false)
let showCancelDialog = ref(false)
let showCancelOwnLeaveDialog = ref(false)
let cancellingOwnLeave = ref(false)
let showCnrDraftDialog = ref(false)
let pendingCnrDetailId = ref(null)
let isFileUploading = ref(false)
let workflow = ref(null)

const formModel = computed({
	get() {
		return props.modelValue
	},
	set(newValue) {
		emit("update:modelValue", newValue)
	},
})

const status = computed(() => {
	if (!props.id) return ""

	if (workflow.value) {
		const stateField = workflow.value.getWorkflowStateField()
		if (stateField) return formModel.value[stateField]
	}

	return formModel.value.status || formModel.value.approval_status
})

const displayStatus = computed(() => {
	if (CNR_DOCTYPES.includes(props.doctype) && status.value === "Draft") {
		return "Waiting for Approval"
	}
	return status.value
})

watch(
	() => formModel.value,
	() => {
		if (!props.id) return

		if (isFormReady.value && !isFormUpdated.value) {
			isFormDirty.value = true
		} else if (isFormUpdated.value) {
			isFormUpdated.value = false
		}
	},
	{ deep: true }
)

watch(
	() => status.value,
	async (value) => {
		if (!value) return
		if (CNR_DOCTYPES.includes(props.doctype) && value === "Draft") {
			statusColor.value = "orange"
			return
		}
		statusColor.value = await guessStatusColor(props.doctype, status.value)
	},
	{ immediate: true }
)

const slotTabs = computed(() => (props.tabs || []).filter((tab) => tab.slot))

// On an existing application the status is what the approver came to see and
// set, and at the end of a long form it sat under the sticky Submit bar.
const STATUS_FIELDS = ["status", "approval_status"]
const displayFields = computed(() => {
	if (!props.id) return props.fields
	const status = props.fields.filter((field) => STATUS_FIELDS.includes(field.fieldname))
	if (!status.length) return props.fields
	return [...status, ...props.fields.filter((field) => !STATUS_FIELDS.includes(field.fieldname))]
})

const tabFields = computed(() => {
	let fieldsByTab = {}
	let fieldList = []
	let firstFieldIndex = 0
	let lastFieldIndex = 0

	props.tabs?.forEach((tab) => {
		// A tab with a slot draws its own content -- a rendered print format, say --
		// and must not eat into the field ranges the field tabs are sliced from.
		if (tab.slot) return
		lastFieldIndex = props.fields.findIndex(
			(field) => field.fieldname === tab.lastField
		)
		fieldList = props.fields.slice(firstFieldIndex, lastFieldIndex + 1)
		fieldsByTab[tab.name] = fieldList
		firstFieldIndex = lastFieldIndex + 1
	})

	return fieldsByTab
})

const attachedFiles = createResource({
	url: "hrms.api.get_attachments",
	params: {
		dt: props.doctype,
		dn: props.id,
	},
	transform(data) {
		return data.map((file) => (file.uploaded = true))
	},
	onSuccess(data) {
		fileAttachments.value = data
	},
})

const handleFileSelect = (e) => {
	if (props.id) {
		uploadAllAttachments(props.doctype, props.id, [...e.target.files])
	} else {
		fileAttachments.value.push(...e.target.files)
	}
}

const handleFileDelete = async (fileObj) => {
	if (fileObj.uploaded) {
		const fileAttachment = new FileAttachment(fileObj)
		await fileAttachment.delete()
		await attachedFiles.reload()
	} else {
		fileAttachments.value = fileAttachments.value.filter(
			(file) => file.name !== fileObj.name
		)
	}
}

async function uploadAllAttachments(documentType, documentName, attachments) {
	isFileUploading.value = true

	const uploadPromises = attachments.map((attachment) => {
		const fileAttachment = new FileAttachment(attachment)
		return fileAttachment
			.upload(documentType, documentName, "")
			.then((fileDoc) => {
				fileDoc.uploaded = true
				if (props.id) {
					fileAttachments.value.push(fileDoc)
				}
			})
	})

	await Promise.allSettled(uploadPromises)
	isFileUploading.value = false
}

// CRUD for doc
const docList = createListResource({
	doctype: props.doctype,
	insert: {
		async onSuccess(data) {
			await uploadAllAttachments(data.doctype, data.name, fileAttachments.value)

			if (isCnrDraftApplication(data) && !canApproveCnr.data) {
				pendingCnrDetailId.value = data.name
				showCnrDraftDialog.value = true
				return
			}

			toast({
				title: __("Success"),
				text: __("{0} created successfully!", [__(props.doctype)]),
				icon: "check-circle",
				position: "bottom-center",
				iconClasses: "text-green-500",
			})

			if (props.doctype === "Leave Application") {
				markAttendanceRefresh()
				const query = router.currentRoute.value.query || {}
				if (query.prefill === "1" || query.ranges) {
					router.replace({ name: "AttendanceDashboard" })
					return
				}
			}

			router.replace({
				name: `${props.doctype.replace(/\s+/g, "")}DetailView`,
				params: { id: data.name },
			})
		},
		onError() {
			toast({
				title: __("Error"),
				text: __("Error creating {0}", [__(props.doctype)]),
				icon: "alert-circle",
				position: "bottom-center",
				iconClasses: "text-red-500",
			})
			console.log(`Error creating ${props.doctype}`)
		},
	},
})

const documentResource = createDocumentResource({
	doctype: props.doctype,
	name: props.id,
	fields: "*",
	setValue: {
		onSuccess() {
			toast({
				title: __("Success"),
				text: __("{0} updated successfully!", [__(props.doctype)]),
				icon: "check-circle",
				position: "bottom-center",
				iconClasses: "text-green-500",
			})
		},
		onError() {
			toast({
				title: __("Error"),
				text: __("Error updating {0}", [__(props.doctype)]),
				icon: "alert-circle",
				position: "bottom-center",
				iconClasses: "text-red-500",
			})
			console.log(`Error updating ${props.doctype}`)
		},
	},
	delete: {
		onSuccess() {
			router.back()
			toast({
				title: __("Success"),
				text: __("{0} deleted successfully!", [__(props.doctype)]),
				icon: "check-circle",
				position: "bottom-center",
				iconClasses: "text-green-500",
			})
		},
		onError() {
			toast({
				title: __("Error"),
				text: __("Error deleting {0}", [__(props.doctype)]),
				icon: "alert-circle",
				position: "bottom-center",
				iconClasses: "text-red-500",
			})
			console.log(`Error deleting ${props.doctype}`)
		},
	},
})

const docPermissions = createResource({
	url: "frappe.client.get_doc_permissions",
	params: { doctype: props.doctype, docname: props.id },
})

const permittedWriteFields = createResource({
	url: "hrms.api.get_permitted_fields_for_write",
	params: { doctype: props.doctype },
})

const canApproveCnr = createResource({
	url: "nepal_hrms.api.cnr_applications.can_approve_cnr_application",
	makeParams: () => ({ employee: formModel.value?.employee }),
})

watch(
	() => formModel.value?.employee,
	(employee) => {
		if (employee && CNR_DOCTYPES.includes(props.doctype)) {
			canApproveCnr.reload()
		}
	}
)

const formButton = computed(() => {
	if (!props.showFormButton) return

	if (props.id && props.isSubmittable && !isFormDirty.value) {
		if (formModel.value.docstatus === 0 && hasPermission("submit")) {
			return "Submit"
		} else if (formModel.value.docstatus === 1 && hasPermission("cancel")) {
			return "Cancel"
		}
	} else if (formModel.value.docstatus !== 2) {
		if (CNR_DOCTYPES.includes(props.doctype) && !hasPermission("submit")) {
			return "Submit Application"
		}
		return "Save"
	}
})

const isSaveAction = computed(() =>
	["Save", "Submit Application"].includes(formButton.value)
)

function showDeleteButton() {
	return props.id && formModel.value.docstatus !== 1 && hasPermission("delete")
}

const canCancelOwnLeave = computed(() => {
	if (props.doctype !== "Leave Application") return false
	if (!props.id) return false
	if (Number(formModel.value?.docstatus || 0) !== 0) return false
	if ((formModel.value?.status || "Open") !== "Open") return false
	const leaveEmployee = formModel.value?.employee
	return !!leaveEmployee && leaveEmployee === employee?.data?.name
})

async function cancelOwnLeaveApplication() {
	cancellingOwnLeave.value = true
	try {
		await call("nepal_hrms.api.leave_application.cancel_own_leave_application", {
			name: props.id,
		})
		showCancelOwnLeaveDialog.value = false
		myLeaves.reload()
		leaveBalance.reload()
		toast({
			title: __("Success"),
			text: __("Leave application cancelled. You can submit a new one."),
			icon: "check-circle",
			iconClasses: "text-green-500",
		})
		router.back()
	} catch (error) {
		toast({
			title: __("Error"),
			text:
				error.messages?.join?.(" ") ||
				error.message ||
				__("Could not cancel the leave application"),
			icon: "alert-circle",
			iconClasses: "text-red-500",
		})
	} finally {
		cancellingOwnLeave.value = false
	}
}

function hasPermission(action) {
	const allowed = docPermissions.data?.permissions[action]
	if (
		CNR_DOCTYPES.includes(props.doctype) &&
		(action === "submit" || action === "cancel")
	) {
		return !!canApproveCnr.data && allowed
	}
	return allowed
}

function isCnrDraftApplication(doc) {
	if (!CNR_DOCTYPES.includes(props.doctype)) return false
	if (!doc) return false
	if (cint(doc.docstatus) !== 0) return false
	const status = doc.status || "Draft"
	return status === "Draft"
}

function cint(v) {
	return Number(v || 0)
}

function confirmCnrDraftDialog() {
	showCnrDraftDialog.value = false
	const id = pendingCnrDetailId.value
	pendingCnrDetailId.value = null
	if (id) {
		router.replace({
			name: `${props.doctype.replace(/\s+/g, "")}DetailView`,
			params: { id },
		})
	}
}

function isFieldReadOnly(field) {
	return (
		Boolean(field.read_only)
		|| isFormReadOnly.value
		|| (props.id && !permittedWriteFields.data?.includes(field.fieldname))
	)
}

function isFieldHidden(field) {
	if (Boolean(field.hidden)) return true
	if (field.fieldname === "custom_rejection_reason") {
		return formModel.value?.status !== "Rejected"
	}
	return false
}

function handleDocInsert() {
	if (!validateMandatoryFields()) return
	docList.insert.submit(formModel.value)
}

function isEmptyValue(value) {
	if (typeof value === "string") return !value.trim()
	return !value
}

function validateMandatoryFields() {
	const errorFields = props.fields
		.filter(
			(field) =>
				field.reqd && !field.hidden && isEmptyValue(formModel.value[field.fieldname])
		)
		.map((field) => field.label)

	if (errorFields.length) {
		formErrorMessage.value = `${errorFields.join(", ")} ${
			errorFields.length > 1 ? "fields are mandatory" : "field is mandatory"
		}`
		return false
	} else {
		formErrorMessage.value = ""
		return true
	}
}

async function handleDocUpdate(action) {
	if (documentResource.doc) {
		let params = { ...formModel.value }

		if (!validateMandatoryFields()) return

		if (action == "submit") {
			params.docstatus = 1
		} else if (action == "cancel") {
			params.docstatus = 2
		}

		await documentResource.setValue.submit(params)
		await documentResource.get.promise
		resetForm()
	}

	if (action === "submit") showSubmitDialog.value = false
	else if (action === "cancel") showCancelDialog.value = false
}

function saveForm() {
	emit("validateForm")

	if (props.id) {
		handleDocUpdate()
	} else if (props.customSubmit) {
		if (!validateMandatoryFields()) return
		emit("submitDocument", { ...formModel.value })
	} else {
		handleDocInsert()
	}
}

function submitOrCancelForm() {
	if (isFormDirty.value) return

	if (formModel.value.docstatus === 0) {
		emit("validateForm")
		showSubmitDialog.value = true
	} else if (formModel.value.docstatus === 1) {
		showCancelDialog.value = true
	}
}

function handleDocDelete() {
	documentResource.delete.submit()
	showDeleteDialog.value = false
}

async function reloadDoc() {
	await documentResource.reload()
	resetForm()
}

function resetForm() {
	formModel.value = { ...documentResource.doc }
	nextTick(() => {
		isFormDirty.value = false
		isFormUpdated.value = true
	})
}

async function setFormattedCurrency() {
	const companyCurrency = await getCompanyCurrency(formModel.value.company)

	props.fields.forEach((field) => {
		if (field.fieldtype !== "Currency") return
		if (!(field.readOnly || isFormReadOnly.value)) return

		if (field.options === "currency") {
			formModel.value[field.fieldname] = formatCurrency(
				formModel.value[field.fieldname],
				formModel.value.currency
			)
		} else {
			formModel.value[field.fieldname] = formatCurrency(
				formModel.value[field.fieldname],
				companyCurrency
			)
		}
	})
}

const isFormReadOnly = computed(() => {
	if (!isFormReady.value) return true
	if (!props.id) return false

	// submitted & cancelled docs are read only
	if (formModel.value.docstatus !== 0) return true

	// read only due to workflow based on current user's roles
	if (workflow.value?.isReadOnly(formModel.value)) return true
})

const isFormReady = computed(() => {
	if (!props.id) return true

	return !documentResource.get.loading && documentResource.doc
})

onMounted(async () => {
	if (props.id) {
		await documentResource.get.promise
		formModel.value = { ...documentResource.doc }
		await docPermissions.reload()
		await permittedWriteFields.reload()
		await attachedFiles.reload()
		await setFormattedCurrency()

		// workflow
		workflow.value = useWorkflow(props.doctype)

		isFormDirty.value = false
	}
})
</script>
